import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); StringTokenizer st = new StringTokenizer(br.readLine()); int[] a = new int[n]; for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken()); System.out.println(isRainbow(a, n) ? "yes" : "no"); } } private static boolean isRainbow(int[] a, int n) { int left = 0, right = n - 1; int current = 1; while (left <= right) { if (a[left] != a[right] || a[left] < 1 || a[left] > 7) return false; if (a[left] == current) { left++; right--; } else if (a[left] == current + 1 && current < 7) { current++; } else { return false; } } return current == 7; } }